param([string]$GameRoot = 'D:\Steam\steamapps\common\Left 4 Dead 2', [switch]$CheckOnly)
$ErrorActionPreference = 'Stop'
$expectedBuild = 'ldb-ipc-c32-dev+06abe08be638118c'
$expectedZip = '2e400df86133c068f08d9a416e97542fd85e7d745d54d41f9b03159d3313cf3a'
$url = 'https://raw.githubusercontent.com/yeyunyyds/L4D2_Dxvk_32to64_Bridge/b148ca9f23f7f37be0f4de7bc9f150abd0220343/l4d2-bridge-steam-workshop-diagnostics-dev-06abe08be638118c-r38202917325.zip'
$files = [ordered]@{
  'bin/dxvk_d3d9.dll' = '5daa7a96e5d848387f8eb691af8753e5c8142fc1d7572e78698d811938d6c1e8'
  'bin/.l4d2bridge/L4D2Bridge64.exe' = '71c7fbe52339c76825f24b151e17e2f539fd6b1053c56d004af7485ee2dcf595'
  'bin/.l4d2bridge/L4D2Bridge32.exe' = '6da992b22cc4a4e44548ad4cdfb7201110b07661f7613f3aa20c58149bd0c02a'
}
$GameRoot = [IO.Path]::GetFullPath($GameRoot)
if (-not (Test-Path -LiteralPath (Join-Path $GameRoot 'left4dead2.exe'))) { throw "Game executable missing: $GameRoot" }
function Assert-Binary($Path, $Hash) {
  if ((Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash -ne $Hash) { throw "Binary SHA256 mismatch: $Path" }
  $text = [Text.Encoding]::ASCII.GetString([IO.File]::ReadAllBytes($Path))
  if (-not $text.Contains($expectedBuild)) { throw "Build identity missing: $Path" }
}
if ($CheckOnly) {
  foreach ($name in $files.Keys) {
    $path = Join-Path $GameRoot $name
    if (-not (Test-Path -LiteralPath $path)) { Write-Output "MISSING $path"; continue }
    $text = [Text.Encoding]::ASCII.GetString([IO.File]::ReadAllBytes($path))
    $build = [regex]::Match($text, 'ldb-[a-z0-9-]+-dev\+[0-9a-f]{16}').Value
    $hash = (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash
    Write-Output "$path : build=$build matched=$($hash -eq $files[$name])"
  }
  return
}
if (Get-Process -Name left4dead2,L4D2Bridge64,L4D2Bridge32 -ErrorAction SilentlyContinue) { throw 'Exit game and both Hosts before installation.' }
$taskDirectory = Join-Path ([IO.Path]::GetTempPath()) ('ldb-workshop-diag-' + [guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $taskDirectory | Out-Null
$zip = Join-Path $taskDirectory 'verified.zip'
Invoke-WebRequest -UseBasicParsing -Uri $url -OutFile $zip
if ((Get-FileHash -LiteralPath $zip -Algorithm SHA256).Hash -ne $expectedZip) { throw 'Downloaded ZIP checksum mismatch; no game files modified.' }
$unpacked = Join-Path $taskDirectory 'unpacked'
Expand-Archive -LiteralPath $zip -DestinationPath $unpacked
foreach ($name in $files.Keys) { Assert-Binary (Join-Path $unpacked $name) $files[$name] }
if (Get-Process -Name left4dead2,L4D2Bridge64,L4D2Bridge32 -ErrorAction SilentlyContinue) { throw 'Game/Host started during download; exit before retrying.' }
$backup = Join-Path $GameRoot ('bin/.l4d2bridge/backups/workshop-diag-' + [guid]::NewGuid().ToString('N'))
foreach ($name in $files.Keys) {
  $destination = Join-Path $GameRoot $name
  if (Test-Path -LiteralPath $destination) {
    $saved = Join-Path $backup $name
    New-Item -ItemType Directory -Force (Split-Path $saved -Parent) | Out-Null
    Copy-Item -LiteralPath $destination -Destination $saved
  }
}
Write-Output "Backup: $backup"
# All originals are backed up before any replacement. Config/backend untouched.
foreach ($name in $files.Keys) {
  $destination = Join-Path $GameRoot $name
  New-Item -ItemType Directory -Force (Split-Path $destination -Parent) | Out-Null
  Copy-Item -LiteralPath (Join-Path $unpacked $name) -Destination $destination -Force
  Assert-Binary $destination $files[$name]
  Write-Output "VERIFIED $destination : $expectedBuild"
}
Write-Output 'Installed matched Workshop diagnostic. Keep current config and set client.steamWebDiagnostics=True; check L4D2_STEAM_WEB in Client log.'
